const byId=id=>catalog.find(x=>x.id===id);
const shopFresh=()=>({inventory:{},equipped:{},experienceCount:{}});
const collectionValue=s=>catalog.reduce((a,x)=>a+(s.shop?.inventory[x.id]?s.shop.inventory[x.id].paid*x.resale:0),0);
function purchaseItem(s,id){let x=byId(id),shop=s.shop;if(!x||!shop||s.cash<x.price||(x.slot!=="experience"&&shop.inventory[id]))return false;change(s,()=>{s.cash-=x.price;s.rep+=x.rep;s.lifestyle+=x.price;if(x.slot==="experience"){shop.experienceCount[id]=(shop.experienceCount[id]||0)+1}else{shop.inventory[id]={paid:x.price,at:s.time};if(!shop.equipped[x.slot])equipItem(s,id)}});return true}
function equipItem(s,id){let x=byId(id);if(!x||!s.shop?.inventory[id])return false;if(x.slot==="outfit"){for(const k of ["top","bottom","outer"])delete s.shop.equipped[k]}else if(["top","bottom","outer"].includes(x.slot)){delete s.shop.equipped.outfit}s.shop.equipped[x.slot]=id;return true}
function sellItem(s,id){let x=byId(id),o=s.shop?.inventory[id];if(!x||!o)return false;change(s,()=>{s.cash+=o.paid*x.resale;delete s.shop.inventory[id];for(const k of Object.keys(s.shop.equipped))if(s.shop.equipped[k]===id)delete s.shop.equipped[k]});return true}
