const TAX_PERIOD=180;
const riskFresh=(s)=>({taxNext:s.time+TAX_PERIOD,earnedMark:s.earned,paid:0,debt:0,lastTax:0,periods:0,next:s.time+90,won:0,lost:0,lostUnits:0,lostValue:0,crisis:null,repair:{available:0,used:false},stabilityVersion:2,technicalRetries:0,claims:R.map(()=>({value:0,rate:0,at:s.time}))});
