const fresh=(now=Date.now())=>{let s=({v:3,cash:100,owned:B.map(()=>0),spent:0,time:0,last:now,works:0,earned:0,rep:0,lux:L.map(()=>false),visits:0,lifestyle:0,casinoNet:0,casinoRounds:0,casinoResult:"",buff:null,event:null,next:90,history:[100],sample:0,news:[],milestones:[],manager:B.map(()=>false),difficulty:"normal",market:marketFresh(),shop:shopFresh()});s.risk=riskFresh(s);return s};
const worth=s=>Math.max(0,s.cash+s.spent+stockValue(s)+collectionValue(s)+L.reduce((a,l,i)=>a+(s.lux[i]?l[1]*.7:0),0)-(s.risk?.debt||0));
const mult=n=>2**[25,50,100,200].filter(x=>n>=x).length;
const baseIncome=(s,market=true,network=true)=>B.reduce((a,b,i)=>a+s.owned[i]*b[3]*mult(s.owned[i])*(s.manager[i]?1.5:1)*(market&&s.event&&s.time<s.event.end&&(s.event.sector===b[1]||s.event.sector==="All")?s.event.mult:1),0)*(network&&s.buff&&s.time<s.buff.end?s.buff.mult:1)*(1+Math.min(s.rep,500)*.0005);
