const rank=s=>1+R.filter((_,i)=>rivalWorth(s,i)>worth(s)).length;
const near=s=>R.map((r,i)=>({name:r[0],value:rivalWorth(s,i),i})).filter(r=>r.value>worth(s)).sort((a,b)=>a.value-b.value)[0];
