function advance(s,now=Date.now(),rand=Math.random){let raw=Math.max(0,(now-s.last)/1000);if(!raw)return 0;let risk=riskInit(s);if(risk.crisis){s.last=now;let c=risk.crisis;if(!c.ready)return 0;c.remaining=Math.max(0,c.remaining-Math.min(raw,2.5));if(c.remaining<=0){if(!c.inputs)retryCrisis(s,"No puzzle inputs detected");else settleCrisis(s,false,rand)}return 0}let dt=Math.min(raw,28800),earn=0;change(s,()=>{let remaining=dt,offline=raw>10;while(remaining>0){let chunk=remaining;if(!offline){if(s.event&&s.event.end>s.time)chunk=Math.min(chunk,s.event.end-s.time);if(s.buff&&s.buff.end>s.time)chunk=Math.min(chunk,s.buff.end-s.time)}let e=baseIncome(s,!offline,!offline)*chunk;earn+=e;s.time+=chunk;remaining=Math.max(0,remaining-chunk)}s.cash+=earn;s.earned+=earn;s.last=now;let taxWasDue=s.time>=risk.taxNext;assessTax(s,earn);if(taxWasDue)risk.next=Math.max(risk.next,s.time+12);evolveMarket(s,rand);if(s.buff&&s.buff.end<=s.time)s.buff=null;if(s.event&&s.event.end<=s.time){s.event=null;s.next=s.time+60+rand()*90}if(!s.event&&s.time>=s.next&&baseIncome(s)>0){let e=EVENTS[Math.floor(rand()*EVENTS.length)];s.event={title:e[0],sector:e[1],mult:e[2],end:s.time+45}}if(s.time-s.sample>=5){s.history.push(worth(s));s.history=s.history.slice(-100);s.sample=s.time}});if(s.time>=risk.next&&risk.taxNext-s.time>=12&&s.owned.reduce((a,b)=>a+b,0)>=3)startCrisis(s,rand);return earn}
function work(s){let pay=10+Math.floor(s.rep/10);change(s,()=>{s.cash+=pay;s.earned+=pay;s.works++;if(s.risk?.debt>0)payTax(s,pay*.25)});return pay}
function buy(s,i,q){if(!B[i])return false;q=q==="max"?max(s,i):q;if(!Number.isInteger(q)||q<1)return false;let c=cost(i,s.owned[i],q);if(!Number.isFinite(c)||c>s.cash+1e-8)return false;s.cash=Math.max(0,s.cash-c);s.spent+=c;s.owned[i]+=q;return true}
